window.kbPageData["views/entry/k-62d9c7a7261583bb"] = {"key":"entry/k-62d9c7a7261583bb","state":{"route":"entry/k-62d9c7a7261583bb"},"node":{"id":"k-62d9c7a7261583bb","mode":"k","title":"化解金融领域风险","type":"概念与词义","domain":"经济","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["finance"],"主类":["概念与词义"],"出处性质":["机构注释"],"学科":["经济"],"来源主题":["发展与治理"],"资料类别":["非时政"]},"directorySummary":"3.化解金融领域风险\n坚持把防控风险作为金融工作的永恒主题。金融既有管理和分散风险的功能，又自带风\n险基因。我国金融体量和复杂程度今非昔比，风险的系统性关联性大大增强。必须增强忧患\n意识，做好风险防控，增强金融体系韧性。\n加快建设金融强国的目标：\n金融强国，应当基于强大的经济基础，具有领先世界的经济…","sources":[{"id":"b3faa643c2c1a8ff","label":"化解金融领域风险","topic":"发展与治理","category":"非时政","text":"3.化解金融领域风险\n坚持把防控风险作为金融工作的永恒主题。金融既有管理和分散风险的功能，又自带风\n险基因。我国金融体量和复杂程度今非昔比，风险的系统性关联性大大增强。必须增强忧患\n意识，做好风险防控，增强金融体系韧性。\n加快建设金融强国的目标：\n金融强国，应当基于强大的经济基础，具有领先世界的经济实力、科技实力和综合国力，\n同时具备一系列关键核心金融要素：拥有强大的货币、强大的中央银行、强大的金融机构、\n强大的国际金融中心、强大的金融监管、强大的金融人才队伍。\n建设金融强国，必须加快构建中国特色现代金融体系：科学稳健的金融调控体系，结构\n合理的金融市场体系，分工协作的金融机构体系，完备有效的金融监管体系，多样化专业性\n的金融产品和服务体系，自主可控、安全高效的金融基础设施体系。\n——《求是》杂志文章《走好中国特色金融发展之路，建设金融强国》","source":{"doc":"6cbfb01fe723bba64b75","first":48,"last":49,"page":48,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"finance","title":"财政金融与宏观调控"}],"units":{"k-62d9c7a7261583bb":[]}};
